CREATE TABLE "brand_assets" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"kind" text NOT NULL,
	"key" text NOT NULL,
	"name" text NOT NULL,
	"short_name" text,
	"league" text,
	"image_url" text,
	"image_kind" text,
	"image_width" integer,
	"image_height" integer,
	"primary_color" text,
	"secondary_color" text,
	"source" text NOT NULL,
	"rights" text DEFAULT 'unreviewed' NOT NULL,
	"attribution" text,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "brand_assets_kind_ck" CHECK ("brand_assets"."kind" in ('team','performer','production','venue','category')),
	CONSTRAINT "brand_assets_rights_ck" CHECK ("brand_assets"."rights" in ('provider_terms','licensed','unreviewed')),
	CONSTRAINT "brand_assets_image_https_ck" CHECK ("brand_assets"."image_url" is null or "brand_assets"."image_url" like 'https://%')
);
